# name: test/sql/hnsw/hnsw_join_macro.test
# group: [hnsw]

require vss

statement ok
CREATE TABLE t1 (id int, vec FLOAT[3]);

statement ok
INSERT INTO t1 SELECT row_number() over (), array_value(a,b,c) FROM range(1,10) ra(a), range(1,10) rb(b), range(1,10) rc(c);

statement ok
CREATE TABLE s(s_vec FLOAT[3]);

statement ok
CREATE INDEX s_vec_idx ON t1 USING HNSW(vec);

statement ok
INSERT INTO s VALUES ([5,5,5]), ([1,1,1]);

statement ok
pragma disable_optimizer;

query I
SELECT bool_and(score <= 1.0) FROM vss_join(s, t1, s_vec, vec, 3) as res;
----
true

query I
SELECT len(matches) = 3 FROM s, vss_match(t1, s_vec, vec, 3) as res;
----
true
true

statement ok
pragma enable_optimizer;

query I
SELECT bool_and(score <= 1.0) FROM vss_join(s, t1, s_vec, vec, 3) as res;
----
true

query I
SELECT len(matches) = 3 FROM s, vss_match(t1, s_vec, vec, 3) as res;
----
true
true

# name: test/sql/hnsw/hnsw_metrics.test
# group: [hnsw]

require vss

require noforcestorage

statement ok
SET profiling_renderer_settings = MAP {'operator_casing': 'upper'};

statement ok
CREATE TABLE t1 (vec FLOAT[3]);

statement ok
INSERT INTO t1 SELECT array_value(a,b,c) FROM range(1,10) ra(a), range(1,10) rb(b), range(1,10) rc(c);


# Test creating indexes with different vector metrics
statement ok
CREATE INDEX my_ip_idx ON t1 USING HNSW (vec) WITH (metric = 'ip');

statement ok
CREATE INDEX my_cos_idx ON t1 USING HNSW (vec) WITH (metric = 'cosine');

statement ok
CREATE INDEX my_l2sq_idx ON t1 USING HNSW (vec) WITH (metric = 'l2sq');

# Make sure we get the index scan plan on the index matching the distance measurement
query II
EXPLAIN SELECT array_negative_inner_product(vec, [1,2,3]::FLOAT[3]) as x FROM t1 ORDER BY x LIMIT 3;
----
physical_plan	<REGEX>:.*HNSW_INDEX_SCAN.*my_ip_idx.*

query II
EXPLAIN SELECT array_cosine_distance(vec, [1,2,3]::FLOAT[3]) as x FROM t1 ORDER BY x LIMIT 3;
----
physical_plan	<REGEX>:.*HNSW_INDEX_SCAN.*my_cos_idx.*

query II
EXPLAIN SELECT array_distance(vec, [1,2,3]::FLOAT[3]) as x FROM t1 ORDER BY x LIMIT 3;
----
physical_plan	<REGEX>:.*HNSW_INDEX_SCAN.*my_l2sq_idx.*

# name: test/sql/hnsw/hnsw_rewrite.test
# group: [hnsw]

require vss

# Test that we rewrite (1 - array_cosine_similarity) to array_cosine_distance

statement ok
CREATE TABLE t1 (v FLOAT[3]);

statement ok
INSERT INTO t1 VALUES ([0.8, 0.8, 0.8]);

query II
EXPLAIN SELECT 1.0 - array_cosine_similarity(v, [0.2,0.2,0.2]::FLOAT[3]) FROM t1;
----
physical_plan	<REGEX>:.*array_cosine_distance.*

statement ok
pragma disable_optimizer;

query II
EXPLAIN SELECT 1.0 - array_cosine_similarity(v, [0.2,0.2,0.2]::FLOAT[3]) FROM t1;
----
physical_plan	<REGEX>:.*array_cosine_similarity.*

query I rowsort RES
SELECT 1.0 - array_cosine_similarity(v, [0.2,0.2,0.2]::FLOAT[3]) FROM t1;

statement ok
pragma enable_optimizer;

query I rowsort RES
SELECT 1.0 - array_cosine_similarity(v, [0.2,0.2,0.2]::FLOAT[3]) FROM t1;

